  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'CONTEXT vigente: artículo no impreso en la edición CEDIJ; texto del legacy pendiente de cotejo con La Gaceta (D5)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CPC_OLA6.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA6')
  WHERE ingest_batch = 'OLA6_CPC_2024_01' AND id IN ('OLA6_CPC_2024_01:CODIGO_PROCESAL_CIVIL:40');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CPC_OLA6.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA6')
  WHERE ingest_batch = 'OLA6_CPC_2024_01' AND id IN ('OLA6_CPC_2024_01:CODIGO_PROCESAL_CIVIL:400', 'OLA6_CPC_2024_01:CODIGO_PROCESAL_CIVIL:783', 'OLA6_CPC_2024_01:CODIGO_PROCESAL_CIVIL:932');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 932 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 932)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 931 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 931)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 1 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 1)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
  UPDATE public.biblioteca_vectores b SET revision_pendiente = true,
    metadata = b.metadata || jsonb_build_object('sustituido_por_lote', 'OLA6_CPC_2024_01', 'sustituido_fecha', '2026-11-24', 'revision_pendiente_motivo', 'Sustituida por HN:CODIGO_PROCESAL_CIVIL V5 (OLA6); oculta, no borrada')
  WHERE ((b.metadata->>'norm_id' = 'HN_CODIGO_PROCESAL_CIVIL' AND (b.id LIKE 'v2civil:mayalex_normativos:%' OR b.id LIKE 'v2civil:mayalex_procedimental:%')) OR b.id LIKE 'mayalex_normativos:cpc_base_a%') AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 2859 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 2859)', n; END IF;
END $do$;
COMMIT;
SELECT count(*) AS filas, count(*) FILTER (WHERE revision_pendiente = false) AS visibles, metadata->>'estado_v' AS estado_v,
  count(*) FILTER (WHERE es_norma_vigente = true AND NOT (metadata ? 'rol')) AS primary_vigentes,
  count(*) FILTER (WHERE metadata->>'rol' = 'CONTEXT') AS context,
  count(*) FILTER (WHERE es_norma_vigente = false) AS derogados,
  count(*) FILTER (WHERE embedding IS NOT NULL) AS con_embedding,
  count(*) FILTER (WHERE encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido) AS sha_ok
FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA6_CPC_2024_01' GROUP BY metadata->>'estado_v';
